// ---------- Profile ----------

export async function updateProfile(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const name = String(formData.get("name") ?? "").trim();
  if (name.length < 1 || name.length > 100) return { error: "Enter a valid name." };
  await db.user.update({ where: { id: user.id }, data: { name } });
  revalidatePath("/dashboard/settings");
  return { ok: true };
}

export async function changePassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const current = String(formData.get("current") ?? "");
  const next = String(formData.get("next") ?? "");
  if (next.length < 8) return { error: "New password must be at least 8 characters." };
  if (!(await bcrypt.compare(current, user.passwordHash))) return { error: "Current password is incorrect." };
  // Bump sessionVersion to evict every other outstanding session, then re-issue a
  // fresh token for THIS session so the user who changed the password stays in.
  await db.user.update({
    where: { id: user.id },
    data: { passwordHash: await bcrypt.hash(next, 12), sessionVersion: { increment: 1 } },
  });
  await createSession(user.id);
  return { ok: true };
}

/**
 * Evict every OTHER logged-in session for this account (a stolen/borrowed device,
 * a shared computer left signed in) while keeping the caller signed in. Same
 * mechanism as a password change: bump sessionVersion so every existing token
 * fails the version check, then re-issue a fresh token for THIS session.
 */
export async function signOutOtherSessions(): Promise<{ ok?: boolean; error?: string }> {
  const user = await requireUser();
  await db.user.update({
    where: { id: user.id },
    data: { sessionVersion: { increment: 1 } },
  });
  await createSession(user.id);
}

export async function resetPassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  const token = String(formData.get("token") ?? "");
  const password = String(formData.get("password") ?? "");
  if (password.length < 8) return { error: "Password must be at least 8 characters." };
  const { createHash } = await import("node:crypto");
  const tokenHash = createHash("sha256").update(token).digest("hex");
  const row = await db.passwordResetToken.findUnique({ where: { tokenHash } });
  if (!row || row.usedAt || row.expiresAt < new Date()) {
    return { error: "This reset link is invalid or has expired. Request a new one." };
  }
  await db.$transaction([
    // Bump sessionVersion so any sessions predating the reset are evicted.
    db.user.update({
      where: { id: row.userId },
      data: { passwordHash: await bcrypt.hash(password, 12), sessionVersion: { increment: 1 } },
    }),
    db.passwordResetToken.update({ where: { id: row.id }, data: { usedAt: new Date() } }),
    db.auditLog.create({ data: { userId: row.userId, action: "user.password_reset_complete" } }),
  ]);
  return { ok: true };
}

