import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { MailboxesView } from "@/components/nx/MailboxesView";
import type { PlanOpt, SubscriptionRow } from "@/components/customer/EmailHosting";
import { CloudflareResultBanner } from "@/components/customer/CloudflareConnect";
import { annualDiscountPct } from "@/lib/annual-discount";

export const dynamic = "force-dynamic";

export default async function EmailHostingPage({
  searchParams,
}: {
  searchParams: Promise<{ paid?: string }>;
}) {
  const { paid } = await searchParams;
  const user = await requireUser();

  const [domains, plans, subscriptions, annualPct] = await Promise.all([
    db.domain.findMany({
      where: { userId: user.id, status: "ACTIVE" },
      orderBy: { name: "asc" },
    }),
    db.emailPlan.findMany({
      where: { active: true },
      orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }],
    }),
    db.emailSubscription.findMany({
      where: { userId: user.id, status: { not: "CANCELLED" } },
      include: { emailPlan: true, mailboxes: { orderBy: { createdAt: "asc" } } },
      orderBy: { createdAt: "desc" },
    }),
    annualDiscountPct(),
  ]);

  const planOpts: PlanOpt[] = plans.map((p) => ({
    id: p.id,
    name: p.name,
    mailboxes: p.mailboxes,
    storageGB: p.storageGB,
    priceCents: p.priceCents,
    termMonths: p.termMonths,
  }));

  const subRows: SubscriptionRow[] = subscriptions.map((s) => ({
    id: s.id,
    domainName: s.domainName,
    status: s.status,
    external: s.external,
    verified: s.verified,
    planName: s.emailPlan.name,
    planMailboxes: s.emailPlan.mailboxes,
    planStorageGB: s.emailPlan.storageGB,
    expiresAt: s.expiresAt ? s.expiresAt.toISOString() : null,
    mailboxes: s.mailboxes.map((m) => ({
      id: m.id,
      address: m.address,
      // The row's REAL status. This was deliberately dropped here, which is why
      // every mailbox rendered a hardcoded amber "Provisioning" badge forever —
      // including one whose Mailcow provisioning had already come back FAILED,
      // so mail to it bounced while the panel implied it was still on its way.
      status: m.status,
      createdAt: m.createdAt.toISOString(),
    })),
  }));

  // Business email provisions synchronously — the subscription row is already
  // ACTIVE by the time `fulfil-checkout.ts` redirects here with `?paid=1` — so
  // there is no multi-step progress to show (same reasoning the domain detail
  // page documents for skipping a full-screen <Provisioning/> takeover). What
  // WAS missing is any acknowledgement at all: a customer landing here after
  // paying saw the same mailbox list as always, with no sign their order went
  // through or hint that a mailbox still needs creating.
  const justPaid = paid === "1" && subscriptions.some((s) => s.status === "ACTIVE");

  return (
    <div className="flex flex-col gap-3">
      {justPaid && (
        <div className="card border-emerald-500/30 bg-emerald-500/[0.06]">
          <div className="flex items-start gap-3">
            <span className="mt-0.5 flex h-9 w-9 flex-none items-center justify-center rounded-full bg-emerald-500/15 text-emerald-300">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M20 6 9 17l-5-5" />
              </svg>
            </span>
            <div>
              <h2 className="font-semibold text-white">Your business email is ready</h2>
              <p className="mt-1 text-sm text-slate-300">
                Create your first mailbox below to start sending and receiving mail on your domain.
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Outcome of a "Connect Cloudflare" round trip, if we just came back from one. */}
      <CloudflareResultBanner />

      <MailboxesView
        domains={domains.map((d) => d.name)}
        plans={planOpts}
        subscriptions={subRows}
        balanceCents={user.balanceCents}
        annualDiscountPct={annualPct}
        email={user.email}
      />
    </div>
  );
}
