      // The raw (possibly registrar-attributed) reason goes here, not on
      // Domain.error — matching the "recovered"/"needs_review" branches above,
      // which log it the same way. Without this, the only place the real
      // diagnostic ever lands is an ephemeral server console line
      // (registrarSafeMessage's own console.error), which is far less
      // discoverable for ops later than a normal audit-log entry.
      await db.auditLog.create({
        data: { userId: user.id, action: "domain.register.failed", detail: `${domain}: ${reason}`.slice(0, 500) },
      });
      return {
        kind: "refunded",
        domainId: record.id,
        message: `Registration failed: ${customerReason.slice(0, 200)} (you were refunded).`,
      };
    }

    // Unknown: leave PENDING and charged, flag for manual review. Refunding
    // here risks giving away a domain we actually paid the registrar for.
    await db.domain.update({
      where: { id: record.id },
      data: { status: "PENDING", error: `NEEDS REVIEW — registration status unconfirmed: ${customerReason}`.slice(0, 500) },
    });
    await db.auditLog.create({
      data: { userId: user.id, action: "domain.register.needs_review", detail: `${domain}: ${reason}`.slice(0, 500) },
    });
    await db.notification.create({
      data: {
        userId: user.id,
        title: `Domain ${domain} needs review`,
        body: "We could not confirm the registration with the registrar. Our team is checking it — no duplicate charge will be made.",
        href: `/dashboard/domains/${record.id}`,
      },
    });
    return {
      kind: "needs-review",
      domainId: record.id,
      message:
        `We could not confirm ${domain} (${customerReason.slice(0, 120)}). ` +
        `It is marked for review — do not retry, you will not be charged twice.`,
    };
  }
}

