export async function createOutstandingEmbedded(opts: {
  user: { id: string; email: string; stripeCustomerId: string | null };
  amountCents: number;
  hostname: string;
  serverId: string;
}): Promise<EmbeddedCheckout | null> {
  if (!stripeConfigured()) return null;
  const due = Math.round(opts.amountCents);
  if (!Number.isFinite(due) || due <= 0) return null;
  const amount = Math.max(STRIPE_MIN_CENTS, due);
  const base = appBase();
  try {
    const session = await stripe().checkout.sessions.create({
      mode: "payment",
      ...(opts.user.stripeCustomerId
        ? { customer: opts.user.stripeCustomerId }
        : { customer_email: opts.user.email }),
      line_items: [
