          price_data: {
            currency: "usd",
            product_data: {
              name: `Nxeon renewal — ${opts.hostname}`,
              description:
                "Settles the outstanding renewal balance. Added to your Nxeon wallet and applied to this renewal automatically.",
            },
            unit_amount: amount,
          },
          quantity: 1,
        },
      ],
      metadata: { nxeonUserId: opts.user.id },
      // Custom Checkout (`ui_mode: "elements"`), not the old `EMBEDDED_UI_MODE`
      // ("embedded_page", Stripe's own prebuilt page) this used to be — the same
      // migration `createCardSetupSession` and `createTopUpPaymentSession` already
      // went through, for the same reason: `EMBEDDED_UI_MODE` renders as an
      // unstyled light Stripe form dropped into a small dark modal (see
      // AddFundsPaymentModal.tsx's doc comment). Mounted client-side via
      // `SettleBalanceModal`'s `<PaymentElement>`. return_url is unchanged — the
      // same fulfilling confirm route either way.
      ui_mode: CUSTOM_CHECKOUT_UI_MODE,
      return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
    }, EMBEDDED_REQUEST_OPTS);
    return session.client_secret
      ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() }
      : null;
  } catch (e) {
    console.error("[cards] could not create embedded outstanding-balance checkout", e);
    return null;
  }
}

